import{_ as a,o as i,c as o,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const m=JSON.parse('{"title":"Come usare questa documentazione?","description":"","frontmatter":{"source_hash":"02a52b4234","source_commit":"4613ad5"},"headers":[],"relativePath":"it/install/usethedoc.md","filePath":"it/install/usethedoc.md"}'),n={name:"it/install/usethedoc.md"};function t(l,e,s,u,c,p){return i(),o("div",null,[...e[0]||(e[0]=[r('<p>Questa documentazione si basa sull&#39;<a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">ultima Nightly Build</a> (considera qualche giorno di ritardo dopo un rilascio).</p><h2 id="if-youre-completely-new-to-xdrip" tabindex="-1"><strong>Se sei nuovo di xDrip</strong> <a class="header-anchor" href="#if-youre-completely-new-to-xdrip" aria-label="Permalink to &quot;**Se sei nuovo di xDrip** {#if-youre-completely-new-to-xdrip}&quot;">​</a></h2><p>Se lo installi per la prima volta, continua con ⇒ <a href="./prerequisites.html">prerequisiti</a> e segui il percorso.</p><h2 id="if-youre-already-using-xdrip" tabindex="-1"><strong>Se usi già xDrip</strong> <a class="header-anchor" href="#if-youre-already-using-xdrip" aria-label="Permalink to &quot;**Se usi già xDrip** {#if-youre-already-using-xdrip}&quot;">​</a></h2><p>Se una funzione descritta qui non c&#39;è nella tua app, potresti dover <a href="./../use/update.html">aggiornare</a> xDrip.<br> In fondo a ogni pagina trovi la versione per cui è stata scritta: se la tua è più vecchia, potrebbe non includere la funzione.</p><br><div class="info custom-block"><p class="custom-block-title">Info</p><p>Le funzioni della modalità ingegnere volutamente non sono documentate.</p></div><br><h3 id="original-documentation" tabindex="-1">Documentazione originale <a class="header-anchor" href="#original-documentation" aria-label="Permalink to &quot;Documentazione originale {#original-documentation}&quot;">​</a></h3><p>Questa documentazione raccoglie varie fonti: quando possibile troverai i link alla <strong>documentazione originale e di riferimento</strong>.<br> Affidati sempre alla documentazione originale, a meno che non sia obsoleta (verrà indicato).</p><h3 id="translation" tabindex="-1">Traduzione <a class="header-anchor" href="#translation" aria-label="Permalink to &quot;Traduzione {#translation}&quot;">​</a></h3><p>La documentazione è disponibile in inglese, francese e italiano. Usa il selettore della lingua in alto nella pagina per cambiare lingua: resterai sulla stessa pagina.<br> Le traduzioni sono in corso: le pagine non ancora tradotte vengono mostrate in inglese, con un avviso. L&#39;inglese è la versione di riferimento; una pagina tradotta la cui versione inglese è cambiata nel frattempo viene segnalata.</p><p>I nomi dei menu e delle impostazioni sono quelli che xDrip mostra in italiano. Se il tuo xDrip è in inglese, ti sarà più facile seguire la <a href="./../../install/usethedoc.html">versione inglese</a> della documentazione.</p><h3 id="search" tabindex="-1">Ricerca <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Ricerca {#search}&quot;">​</a></h3><p>Puoi cercare un menu o un termine nella documentazione con la lente in alto a destra, nella lingua che stai leggendo.</p><h3 id="typo-error-missing-information" tabindex="-1">Refusi, errori, informazioni mancanti <a class="header-anchor" href="#typo-error-missing-information" aria-label="Permalink to &quot;Refusi, errori, informazioni mancanti {#typo-error-missing-information}&quot;">​</a></h3><p>Puoi segnalarli aprendo una <a href="https://github.com/xdrip/xdrip_docs/issues" target="_blank" rel="noreferrer">issue</a> su GitHub.</p><p>Puoi anche contribuire creando una <a href="https://github.com/xdrip/xdrip_docs/pulls" target="_blank" rel="noreferrer">pull request</a> nel repository principale.</p><p>Puoi inoltre lasciare un commento nel gruppo Facebook principale <a href="https://www.facebook.com/groups/xDripG5" target="_blank" rel="noreferrer">xDrip</a> (GitHub resta consigliato).</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer"><em>Ultima modifica</em></a></p>',21)])])}const h=a(n,[["render",t]]);export{m as __pageData,h as default};
